 firstName: 'Barbara',
 lastName: 'Hepworth',
 email: 'bhepworth@sculpture.com'
 });

function handleFirstNameChange(e) {
 setPerson({
 ...person,
 firstName: e.target.value
 });
 }

function handleLastNameChange(e) {
 setPerson({
 ...person,
 lastName: e.target.value
 });
 }

function handleEmailChange(e) {
 setPerson({
 ...person,
 email: e.target.value
 });
 }

return (
 <>
 <label>
 First name:
