 </li>
 ))}
 </ul>
 );
}

function Task({ task }) {
 const [isEditing, setIsEditing] = useState(false);
 const dispatch = useContext(TasksDispatchContext);
 let taskContent;
 if (isEditing) {
 taskContent = (
 <>
 <input
 value={task.text}
 onChange={e => {
 dispatch({
 type: 'changed',
 task: {
 ...task,
 text: e.target.value
 }
 });
 }} />
 <button onClick={() => setIsEditing(false)}>
 Save
 </button>
 </>
 );
