 taskContent = (
 <>
 {task.text}
 <button onClick={() => setIsEditing(true)}>
 Edit
 </button>
 </>
 );
 }
 return (
 <label>
 <input
 type="checkbox"
 checked={task.done}
 onChange={e => {
 dispatch({
 type: 'changed',
