 console.log('❌ Too many cats in the list!');
 }
 return () => {
 // 🚩 No cleanup, this is a bug!
 }
 }}
 >
 <img src={cat.src} />
 </li>
 ))}
 </ul>
 </div>
 </>
 );
}

function setupCatList() {
 const catList = [];
 for (let i = 0; i < 10; i++) {
 catList.push({type: 'neo', src: "https://placecats.com/neo/320/240?" + i});
 }
 for (let i = 0; i < 10; i++) {
 catList.push({type: 'millie', src: "https://placecats.com/millie/320/240?" + i});
 }

return catList;
}
```

With Strict Mode, you immediately see that there is a problem. Strict Mode runs an extra setup+cleanup cycle for every callback ref. This callback ref has no cleanup logic, so it adds refs but doesn’t remove them. This is a hint that you’re missing a cleanup function.

Strict Mode lets you eagerly find mistakes in callback refs. When you fix your callback by adding a cleanup function in Strict Mode, you also fix many possible future production bugs like the “Scroll to” bug from before:

```
import { useRef, useState } from "react";

export default function CatFriends() {
 const itemsRef = useRef([]);
 const [catList, setCatList] = useState(setupCatList);
 const [cat, setCat] = useState('neo');

function scrollToCat(index) {
 const list = itemsRef.current;
 const {node} = list[index];
 node.scrollIntoView({
 behavior: "smooth",
 block: "nearest",
 inline: "center",
 });
 }

const cats = catList.filter(c => c.type === cat)

return (
 <>
 <nav>
 <button onClick={() => setCat('neo')}>Neo</button>
 <button onClick={() => setCat('millie')}>Millie</button>
 </nav>
 <hr />
 <nav>
 <span>Scroll to:</span>{cats.map((cat, index) => (
 <button key={cat.src} onClick={() => scrollToCat(index)}>
 {index}
 </button>
 ))}
 </nav>
 <div>
 <ul>
 {cats.map((cat) => (
 <li
 key={cat.src}
 ref={(node) => {
 const list = itemsRef.current;
 const item = {cat: cat, node};
 list.push(item);
 console.log(`✅ Adding cat to the map. Total cats: ${list.length}`);
 if (list.length > 10) {
 console.log('❌ Too many cats in the list!');
 }
 return () => {
 list.splice(list.indexOf(item), 1);
 console.log(`❌ Removing cat from the map. Total cats: ${itemsRef.current.length}`);
 }
 }}
 >
 <img src={cat.src} />
 </li>
 ))}
 </ul>
 </div>
 </>
 );
}

function setupCatList() {
 const catList = [];
 for (let i = 0; i < 10; i++) {
 catList.push({type: 'neo', src: "https://placecats.com/neo/320/240?" + i});
 }
 for (let i = 0; i < 10; i++) {
 catList.push({type: 'millie', src: "https://placecats.com/millie/320/240?" + i});
 }

return catList;
}
```

Now on inital mount in StrictMode, the ref callbacks are all setup, cleaned up, and setup again:

```
...✅ Adding animal to the map. Total animals: 10...❌ Removing animal from the map. Total animals: 0...✅ Adding animal to the map. Total animals: 10
```

This is expected. Strict Mode confirms that the ref callbacks are cleaned up correctly, so the size never grows above the expected amount. After the fix, there are no memory leaks, and all the features work as expected.

Without Strict Mode, it was easy to miss the bug until you clicked around to app to notice broken features. Strict Mode made the bugs appear right away, before you push them to production.

### Fixing deprecation warnings enabled by Strict Mode

React warns if some component anywhere inside a <StrictMode> tree uses one of these deprecated APIs:

- UNSAFE_ class lifecycle methods like UNSAFE_componentWillMount. See alternatives.

These APIs are primarily used in older class components so they rarely appear in modern apps.

- Canary only Loading images. Suspense doesn’t wait for images by default, but during a <ViewTransition> update, React blocks the boundary until the image loads, up to a timeout. Adding an onLoad handler opts a specific image out. See an example below.

- Experimental only Performing CPU-bound render work inside a <Suspense defer> boundary.

### Note

#### Suspense-enabled frameworks

A Suspense-enabled framework gives you a way to read data in your component in a way that activates the closest Suspense boundary. The exact way you load your data depends on your framework, and you’ll find the details in its documentation. Under the hood, a Suspense-enabled framework maintains a cache of Promises and calls use to suspend on a Promise.

Without a framework, you can read a Promise with use directly, as long as the Promise is cached so the same instance is reused across renders.

## Usage

### Displaying a fallback while content is loading

You can wrap any part of your application with a Suspense boundary:

```
<Suspense fallback={<Loading />}> <Albums /></Suspense>
```

React will display your loading fallback until all the code and data needed by the children has been loaded.

In the example below, the Albums component suspends while fetching the list of albums. Until it’s ready to render, React switches the closest Suspense boundary above to show the fallback—your Loading component. Then, when the data loads, React hides the Loading fallback and renders the Albums component with data.

```
import { Suspense } from 'react';
import Albums from './Albums.js';

export default function ArtistPage({ artist }) {
 return (
 <>
 <h1>{artist.name}</h1>
 <Suspense fallback={<Loading />}>
 <Albums artistId={artist.id} />
 </Suspense>
 </>
 );
}

function Loading() {
 return <h2>🌀 Loading...</h2>;
}
```

By contrast, code that fetches data outside of use, such as inside an Effect, does not activate the boundary:

```
import { Suspense } from 'react';
import EffectAlbums from './EffectAlbums.js';

export default function ArtistPage({ artist }) {
 return (
 <>
 <h1>{artist.name}</h1>
 <Suspense fallback={<Loading />}>
 <EffectAlbums artistId={artist.id} />
 </Suspense>
 </>
 );
}

function Loading() {
 return <h2>🌀 Loading...</h2>;
}
```

During streaming server rendering, a boundary also activates while its HTML is still streaming in. With any streaming server rendering API, React sends the shell with the fallback first, then streams in each boundary’s HTML and swaps out its fallback as that content arrives. Press “Render the page” to watch the page stream in:

```
import { flushReadableStreamToFrame } from './demo-helpers.js';
import { Suspense, use } from 'react';
import { renderToReadableStream } from 'react-dom/server';

let posts = null;

function Posts() {
 const text = use(posts.promise);
 return <p>{text}</p>;
}

function ProfilePage() {
 return (
 <html>
 <body>
 <h1>Alice</h1>
 <p>Photographer and traveler.</p>
 <Suspense fallback={<p>⌛ Loading posts...</p>}>
 <Posts />
 </Suspense>
 </body>
 </html>
 );
}

async function main(frame) {
 posts = Promise.withResolvers();
 const stream = await renderToReadableStream(<ProfilePage />);

// The posts resolve after the shell has streamed, so React
 // streams their HTML in and swaps out the fallback.
 setTimeout(() => {
 posts.resolve(
 'Just got back from two weeks along the coast. The drive ' +
 'was longer than expected, but every stop was worth it. ' +
 'A full write-up and more photos are coming soon.'
 );
 }, 1500);

await flushReadableStreamToFrame(stream, frame);
}

document.getElementById('render').addEventListener('click', () => {
 main(document.getElementById('container'));
});
```

### Revealing content together at once

By default, the whole tree inside Suspense is treated as a single unit. For example, even if only one of these components suspends waiting for some data, all of them together will be replaced by the loading indicator:

```
<Suspense fallback={<Loading />}> <Biography /> <Panel> <Albums /> </Panel></Suspense>
```

Then, after all of them are ready to be displayed, they will all appear together at once.

In the example below, both Biography and Albums fetch some data. However, because they are grouped under a single Suspense boundary, these components always “pop in” together at the same time.

```
import { Suspense } from 'react';
import Albums from './Albums.js';
import Biography from './Biography.js';
import Panel from './Panel.js';

export default function ArtistPage({ artist }) {
 return (
 <>
 <h1>{artist.name}</h1>
 <Suspense fallback={<Loading />}>
 <Biography artistId={artist.id} />
 <Panel>
 <Albums artistId={artist.id} />
 </Panel>
 </Suspense>
 </>
 );
}

function Loading() {
 return <h2>🌀 Loading...</h2>;
}
```

Components that load data don’t have to be direct children of the Suspense boundary. For example, you can move Biography and Albums into a new Details component. This doesn’t change the behavior. Biography and Albums share the same closest parent Suspense boundary, so their reveal is coordinated together.

```
<Suspense fallback={<Loading />}> <Details artistId={artist.id} /></Suspense>function Details({ artistId }) { return ( <> <Biography artistId={artistId} /> <Panel> <Albums artistId={artistId} /> </Panel> </> );}
```

### Revealing nested content as it loads

When a component suspends, the closest parent Suspense component shows the fallback. This lets you nest multiple Suspense components to create a loading sequence. Each Suspense boundary’s fallback will be filled in as the next level of content becomes available. For example, you can give the album list its own fallback:

```
<Suspense fallback={<BigSpinner />}> <Biography /> <Suspense fallback={<AlbumsGlimmer />}> <Panel> <Albums /> </Panel> </Suspense></Suspense>
```

With this change, displaying the Biography doesn’t need to “wait” for the Albums to load.

When a component suspends, the closest parent Suspense component shows the fallback. This lets you nest multiple Suspense components to create a loading sequence. Each Suspense boundary’s fallback will be filled in as the next level of content becomes available. For example, you can give the album list its own fallback:

```
<Suspense fallback={<BigSpinner />}> <Biography /> <Suspense fallback={<AlbumsGlimmer />}> <Panel> <Albums /> </Panel> </Suspense></Suspense>
```

With this change, displaying the Biography doesn’t need to “wait” for the Albums to load.

The sequence will be:

- If Biography hasn’t loaded yet, BigSpinner is shown in place of the entire content area.

- Once Biography finishes loading, BigSpinner is replaced by the content.

- If Albums hasn’t loaded yet, AlbumsGlimmer is shown in place of Albums and its parent Panel.

- Finally, once Albums finishes loading, it replaces AlbumsGlimmer.

```
import { Suspense } from 'react';
import Albums from './Albums.js';
import Biography from './Biography.js';
import Panel from './Panel.js';

export default function ArtistPage({ artist }) {
 return (
 <>
 <h1>{artist.name}</h1>
 <Suspense fallback={<BigSpinner />}>
 <Biography artistId={artist.id} />
 <Suspense fallback={<AlbumsGlimmer />}>
 <Panel>
 <Albums artistId={artist.id} />
 </Panel>
 </Suspense>
 </Suspense>
 </>
 );
}

function BigSpinner() {
 return <h2>🌀 Loading...</h2>;
}

function AlbumsGlimmer() {
 return (
 <div className="glimmer-panel">
 <div className="glimmer-line" />
 <div className="glimmer-line" />
 <div className="glimmer-line" />
 </div>
 );
}
```

Suspense boundaries let you coordinate which parts of your UI should always “pop in” together at the same time, and which parts should progressively reveal more content in a sequence of loading states. You can add, move, or delete Suspense boundaries in any place in the tree without affecting the rest of your app’s behavior.

Don’t put a Suspense boundary around every component. Suspense boundaries should not be more granular than the loading sequence that you want the user to experience. If you work with a designer, ask them where the loading states should be placed—it’s likely that they’ve already included them in their design wireframes.

### Showing stale content while fresh content is loading

In this example, the SearchResults component suspends while fetching the search results. Type "a", wait for the results, and then edit it to "ab". The results for "a" will get replaced by the loading fallback.

```
import { Suspense, useState } from 'react';
import SearchResults from './SearchResults.js';

export default function App() {
 const [query, setQuery] = useState('');
 return (
 <>
 <label>
 Search albums:
 <input value={query} onChange={e => setQuery(e.target.value)} />
 </label>
 <Suspense fallback={<h2>Loading...</h2>}>
 <SearchResults query={query} />
 </Suspense>
 </>
 );
}
```

A common alternative UI pattern is to defer updating the list and to keep showing the previous results until the new results are ready. The useDeferredValue Hook lets you pass a deferred version of the query down:

```
export default function App() { const [query, setQuery] = useState(''); const deferredQuery = useDeferredValue(query); return ( <> <label> Search albums: <input value={query} onChange={e => setQuery(e.target.value)} /> </label> <Suspense fallback={<h2>Loading...</h2>}> <SearchResults query={deferredQuery} /> </Suspense> </> );}
```

The query will update immediately, so the input will display the new value. However, the deferredQuery will keep its previous value until the data has loaded, so SearchResults will show the stale results for a bit.

To make it more obvious to the user, you can add a visual indication when the stale result list is displayed:

```
<div style={{ opacity: query !== deferredQuery ? 0.5 : 1}}> <SearchResults query={deferredQuery} /></div>
```

Enter "a" in the example below, wait for the results to load, and then edit the input to "ab". Notice how instead of the Suspense fallback, you now see the dimmed stale result list until the new results have loaded:

```
import { Suspense, useState, useDeferredValue } from 'react';
import SearchResults from './SearchResults.js';

export default function App() {
 const [query, setQuery] = useState('');
 const deferredQuery = useDeferredValue(query);
 const isStale = query !== deferredQuery;
 return (
 <>
 <label>
 Search albums:
 <input value={query} onChange={e => setQuery(e.target.value)} />
 </label>
 <Suspense fallback={<h2>Loading...</h2>}>
 <div style={{ opacity: isStale ? 0.5 : 1 }}>
 <SearchResults query={deferredQuery} />
 </div>
 </Suspense>
 </>
 );
}
```

### Note

Both deferred values and Transitions let you avoid showing Suspense fallback in favor of inline indicators. Transitions mark the whole update as non-urgent so they are typically used by frameworks and router libraries for navigation. Deferred values, on the other hand, are mostly useful in application code where you want to mark a part of UI as non-urgent and let it “lag behind” the rest of the UI.

### Preventing already revealed content from hiding

When a component suspends, the closest parent Suspense boundary switches to showing the fallback. This can lead to a jarring user experience if it was already displaying some content. Try pressing this button:

```
import { Suspense, useState } from 'react';
import IndexPage from './IndexPage.js';
import ArtistPage from './ArtistPage.js';
import Layout from './Layout.js';

export default function App() {
 return (
 <Suspense fallback={<BigSpinner />}>
 <Router />
 </Suspense>
 );
}

function Router() {
 const [page, setPage] = useState('/');

function navigate(url) {
 setPage(url);
 }

let content;
 if (page === '/') {
 content = (
 <IndexPage navigate={navigate} />
 );
 } else if (page === '/the-beatles') {
 content = (
 <ArtistPage
 artist={{
 id: 'the-beatles',
 name: 'The Beatles',
 }}
 />
 );
 }
 return (
 <Layout>
 {content}
 </Layout>
 );
}

```
import { Suspense, useState } from 'react';
import IndexPage from './IndexPage.js';
import ArtistPage from './ArtistPage.js';
import Layout from './Layout.js';

export default function App() {
 return (
 <Suspense fallback={<BigSpinner />}>
 <Router />
 </Suspense>
 );
}

function Router() {
 const [page, setPage] = useState('/');

function navigate(url) {
 setPage(url);
 }

let content;
 if (page === '/') {
 content = (
 <IndexPage navigate={navigate} />
 );
 } else if (page === '/the-beatles') {
 content = (
 <ArtistPage
 artist={{
 id: 'the-beatles',
 name: 'The Beatles',
 }}
 />
 );
 }
 return (
 <Layout>
 {content}
 </Layout>
 );
}

function BigSpinner() {
 return <h2>🌀 Loading...</h2>;
}
```

When you pressed the button, the Router component rendered ArtistPage instead of IndexPage. A component inside ArtistPage suspended, so the closest Suspense boundary started showing the fallback. The closest Suspense boundary was near the root, so the whole site layout got replaced by BigSpinner.

To prevent this, you can mark the navigation state update as a Transition with startTransition:

```
function Router() { const [page, setPage] = useState('/'); function navigate(url) { startTransition(() => { setPage(url); }); } // ...
```

This tells React that the state transition is not urgent, and it’s better to keep showing the previous page instead of hiding any already revealed content. Now clicking the button “waits” for the Biography to load:

```
import { Suspense, startTransition, useState } from 'react';
import IndexPage from './IndexPage.js';
import ArtistPage from './ArtistPage.js';
import Layout from './Layout.js';

export default function App() {
 return (
 <Suspense fallback={<BigSpinner />}>
 <Router />
 </Suspense>
 );
}

function Router() {
 const [page, setPage] = useState('/');

function navigate(url) {
 startTransition(() => {
 setPage(url);
 });
 }

let content;
 if (page === '/') {
 content = (
 <IndexPage navigate={navigate} />
 );
 } else if (page === '/the-beatles') {
 content = (
 <ArtistPage
 artist={{
 id: 'the-beatles',
 name: 'The Beatles',
 }}
 />
 );
 }
 return (
 <Layout>
 {content}
 </Layout>
 );
}

function BigSpinner() {
 return <h2>🌀 Loading...</h2>;
}
```

A Transition doesn’t wait for all content to load. It only waits long enough to avoid hiding already revealed content. For example, the website Layout was already revealed, so it would be bad to hide it behind a loading spinner. However, the nested Suspense boundary around Albums is new, so the Transition doesn’t wait for it.

### Note

Suspense-enabled routers are expected to wrap the navigation updates into Transitions by default.

### Indicating that a Transition is happening

In the above example, once you click the button, there is no visual indication that a navigation is in progress. To add an indicator, you can replace startTransition with useTransition which gives you a boolean isPending value. In the example below, it’s used to change the website header styling while a Transition is happening:

```
import { Suspense, useState, useTransition } from 'react';
import IndexPage from './IndexPage.js';
import ArtistPage from './ArtistPage.js';
import Layout from './Layout.js';

export default function App() {
 return (
 <Suspense fallback={<BigSpinner />}>
 <Router />
 </Suspense>
 );
}

function Router() {
 const [page, setPage] = useState('/');
 const [isPending, startTransition] = useTransition();

function navigate(url) {
 startTransition(() => {
 setPage(url);
 });
 }

let content;
 if (page === '/') {
 content = (
 <IndexPage navigate={navigate} />
 );
 } else if (page === '/the-beatles') {
 content = (
 <ArtistPage
 artist={{
 id: 'the-beatles',
 name: 'The Beatles',
 }}
 />
 );
 }
 return (
 <Layout isPending={isPending}>
 {content}
 </Layout>
 );
}

function BigSpinner() {
 return <h2>🌀 Loading...</h2>;
}
```

### Resetting Suspense boundaries on navigation

During a Transition, React avoids hiding already revealed content. However, when you navigate to different content, such as another user’s profile, you’ll want the boundary to show the fallback instead of the previous content. You can express this with a key:

```
<ProfilePage key={queryParams.id} />
```

With a different key, React treats the profiles as different content and resets the Suspense boundary during navigation. The key can go on the boundary itself or on a component above it. Suspense-integrated routers should do this automatically.

In the example below, opening the profile page loads the first profile. Pressing “Bob” navigates to a different profile, and the key resets the boundary, so the fallback shows instead of the previous user’s bio. Try removing the key: the previous bio stays visible while the next one loads:

```
import { Suspense, useState, startTransition } from 'react';
import Bio from './Bio.js';
import { fetchBio } from './data.js';

export default function ProfilePage() {
 const [user, setUser] = useState(() => ({
 id: 'alice',
 bioPromise: fetchBio('alice'),
 }));
 function navigate(id) {
 startTransition(() => {
 setUser({ id, bioPromise: fetchBio(id) });
 });
 }
 return (
 <>
 <button onClick={() => navigate('alice')}>
 Alice
 </button>
 <button onClick={() => navigate('bob')}>
 Bob
 </button>
 <Suspense key={user.id} fallback={<p>⌛ Loading profile...</p>}>
 <Bio bioPromise={user.bioPromise} />
 </Suspense>
 </>
 );
}
```

### Providing a fallback for server errors and client-only content

If you use one of the streaming server rendering APIs (or a framework that relies on them), React will also use your <Suspense> boundaries to handle errors on the server. If a component throws an error on the server, React will not abort the server render. Instead, it will find the closest <Suspense> component above it and include its fallback (such as a spinner) into the generated server HTML. The user will see a spinner at first.

### Providing a fallback for server errors and client-only content

If you use one of the streaming server rendering APIs (or a framework that relies on them), React will also use your <Suspense> boundaries to handle errors on the server. If a component throws an error on the server, React will not abort the server render. Instead, it will find the closest <Suspense> component above it and include its fallback (such as a spinner) into the generated server HTML. The user will see a spinner at first.

On the client, React will attempt to render the same component again. If it errors on the client too, React will throw the error and display the closest Error Boundary. However, if it does not error on the client, React will not display the error to the user since the content was eventually displayed successfully.

You can use this to opt out some components from rendering on the server. To do this, throw an error in the server environment and then wrap them in a <Suspense> boundary to replace their HTML with fallbacks:

```
<Suspense fallback={<Loading />}> <Chat /></Suspense>function Chat() { if (typeof window === 'undefined') { throw Error('Chat should only render on the client.'); } // ...}
```

The server HTML will include the loading indicator. It will be replaced by the Chat component on the client.

### Waiting for a stylesheet to load

A stylesheet rendered with <link rel="stylesheet"> and a precedence prop blocks the Suspense boundary until the stylesheet loads, up to a timeout, so the content doesn’t appear unstyled.

In the example below, the Card component renders a stylesheet with precedence. Press “Show card”: React shows the fallback until the stylesheet has loaded, and then reveals the card with its styles applied.

For comparison, the second button performs the same update without React, in a separate document. Nothing waits for the stylesheet, so the card’s text appears in a fallback font first and then switches:

```
import { Suspense, useState, startTransition } from 'react';
import { freshStylesheetUrl } from './styles.js';
import VanillaCard from './VanillaCard.js';

function Card({ href }) {
 return (
 <>
 <link rel="stylesheet" href={href} precedence="default" />
 <div className="fancy-card">This card uses a font from the stylesheet.</div>
 </>
 );
}

export default function App() {
 const [href, setHref] = useState(null);
 return (
 <>
 <button
 onClick={() => {
 startTransition(() => {
 setHref(freshStylesheetUrl());
 });
 }}>
 Show card
 </button>
 {href && (
 <Suspense fallback={<p>⌛ Loading styles...</p>}>
 <Card href={href} />
 </Suspense>
 )}
 <hr />
 <VanillaCard />
 </>
 );
}
```

### Canary only Animating from Suspense content

Suspense composes with <ViewTransition> to animate the swap from the fallback to the content. Wrap the boundary in a <ViewTransition>, and React treats the swap as an update, cross-fading between the fallback and the content by default:

```
import {ViewTransition, useState, startTransition, Suspense} from 'react';
import {Video, VideoPlaceholder} from './Video';
import {useLazyVideoData} from './data';

function LazyVideo() {
 const video = useLazyVideoData();
 return <Video video={video} />;
}

export default function Component() {
 const [showItem, setShowItem] = useState(false);
 return (
 <>
 <button
 onClick={() => {
 startTransition(() => {
 setShowItem((prev) => !prev);
 });
 }}>
 {showItem ? '➖' : '➕'}
 </button>
 {showItem ? (
 <ViewTransition>
 <Suspense fallback={<VideoPlaceholder />}>
 <LazyVideo />
 </Suspense>
 </ViewTransition>
 ) : null}
 </>
 );
}
```

### Note

Where you place the <ViewTransition> relative to the boundary determines whether the fallback and content cross-fade as one update or animate as separate exit and enter animations. You can also customize the animation with View Transition classes.

Learn more about animating from Suspense content.

### Canary only Waiting for a font to load

When a <ViewTransition> animates a Suspense boundary’s reveal, React waits for new fonts the content introduces, up to a timeout, so the text doesn’t flash with a fallback font. This only happens during a <ViewTransition> update.

In the example below, the Suspense boundary is wrapped in a <ViewTransition>, and the Quote component suspends while its data loads. Rendering the quote starts its font download. React keeps the fallback visible until the font has loaded, so the quote appears already in its font.

For comparison, the second button performs the same update without React. Nothing waits for the font, so the text appears in a fallback font first and then switches:

```
import { ViewTransition, Suspense, use, useState, startTransition } from 'react';
import { fetchQuote } from './data.js';
import { freshFontUrl } from './font.js';
import VanillaQuote from './VanillaQuote.js';

function Quote({ fontSrc }) {
 const quote = use(fetchQuote());
 return (
 <>
 <style href={fontSrc} precedence="default">
 {`@font-face {
 font-family: 'Fancy';
 src: url(${fontSrc}) format('truetype');
 font-display: swap;
 }`}
 </style>
 <p className="quote fancy">{quote}</p>
 </>
 );
}

export default function App() {
 const [fontSrc, setFontSrc] = useState(null);
 return (
 <>
 <button
 onClick={() => {
 startTransition(() => {
 setFontSrc(freshFontUrl());
 });
 }}>
 Show quote
 </button>
 {fontSrc && (
 <ViewTransition>
 <Suspense fallback={<p className="quote">⌛ Loading quote...</p>}>
 <Quote fontSrc={fontSrc} />
 </Suspense>
 </ViewTransition>
 )}
 <hr />
 <VanillaQuote />
 </>
 );
}
```

### Canary only Waiting for an image to load

When a <ViewTransition> animates a Suspense boundary’s reveal, React waits for visible images to load, up to a timeout, so the animation doesn’t start with a half-loaded image. This only happens during a <ViewTransition> update. Adding an onLoad handler opts a specific image out, even inside a <ViewTransition>.

export default function App() {
 const [fontSrc, setFontSrc] = useState(null);
 return (
 <>
 <button
 onClick={() => {
 startTransition(() => {
 setFontSrc(freshFontUrl());
 });
 }}>
 Show quote
 </button>
 {fontSrc && (
 <ViewTransition>
 <Suspense fallback={<p className="quote">⌛ Loading quote...</p>}>
 <Quote fontSrc={fontSrc} />
 </Suspense>
 </ViewTransition>
 )}
 <hr />
 <VanillaQuote />
 </>
 );
}
```

### Canary only Waiting for an image to load

When a <ViewTransition> animates a Suspense boundary’s reveal, React waits for visible images to load, up to a timeout, so the animation doesn’t start with a half-loaded image. This only happens during a <ViewTransition> update. Adding an onLoad handler opts a specific image out, even inside a <ViewTransition>.

In the example below, the Suspense boundary is wrapped in a <ViewTransition> and shows a profile skeleton until the portrait has loaded.

For comparison, the second button performs the same update without React. Nothing waits for the image, so the card appears immediately and the image pops in when it loads:

```
import { ViewTransition, Suspense, useState, startTransition } from 'react';
import { freshImageUrl } from './image.js';
import VanillaProfile from './VanillaProfile.js';

function Profile({ src }) {
 return (
 <div className="card">
 <img src={src} alt="Jack Pope" width={80} height={80} />
 <p>Jack Pope</p>
 </div>
 );
}

function ProfilePlaceholder() {
 return (
 <div className="card">
 <div className="avatar-placeholder" />
 <p className="name-placeholder">&nbsp;</p>
 </div>
 );
}

export default function App() {
 const [src, setSrc] = useState(null);
 return (
 <>
 <button
 onClick={() => {
 startTransition(() => {
 setSrc(freshImageUrl());
 });
